mapper.select:
select tod.id, tod.main_id, tod.sku_id, tod.sku_no, tod.qty, tod.out_warehouse_location, tod.source_detail_id, tod.remark from transfer_out tot inner join transfer_out_detail tod on tot.id = tod.main_id and tod.is_deleted = false
tot.is_deleted = false and tot.invalid_status = false and tod.source_detail_id in
#{item}

select tod.id, tod.create_user_id, tod.create_user_name, tod.create_time, tod.update_user_id, tod.update_user_name, tod.update_time, tod.version, tod.is_deleted, tod.main_id, tod.sku_id, tod.sku_no, tod.qty, tod.out_warehouse_location, tod.remark, tod.source_detail_id, tod.unit from transfer_out tot inner join transfer_out_detail tod on tot.id = tod.main_id and tod.is_deleted = false WHERE tot.is_deleted = false and tot.invalid_status = false
AND tod.sku_no ILIKE concat('%',#{param.remoteSearchSku}::text,'%')
AND tod.sku_no IN
#{item}
AND tod.main_id = #{param.sourceId}
